'use strict';
const $=s=>document.querySelector(s), KEY='serendib-portfolio-v1';
const dateToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const uid=()=>crypto.randomUUID();
const num=(n,d=2)=>Number(n).toLocaleString('en-LK',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=n=>'LKR '+num(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
const colors=['#315c40','#7b9a63','#bad397','#d5dfbc','#e7d5ac','#9ab7af'];
const emptyState=()=>({version:2,demo:false,trades:[],openings:[],research:{},statement:null,dividends:[],quotes:{},watchlist:[]});
function demoState(){const s=emptyState();s.demo=true;const rows=[['JKH.N0000','John Keells Holdings','Capital goods',5000,18.5,21.3,'2026-01-12'],['COMB.N0000','Commercial Bank','Banks',800,142,157.5,'2026-02-09'],['HAYL.N0000','Hayleys','Capital goods',600,108,120.5,'2026-03-16'],['DIAL.N0000','Dialog Axiata','Telecommunication',3000,13.2,15.1,'2026-05-08'],['CARG.N0000','Cargills (Ceylon)','Retailing',180,430,414,'2026-07-21']];for(const [symbol,name,sector,qty,price,current,date] of rows){s.trades.push({id:uid(),type:'buy',symbol,name,sector,qty,price,fee:Math.round(qty*price*.01),date});s.quotes[symbol]={price:current,date:'2026-10-26'};}s.dividends=[{id:uid(),symbol:'COMB.N0000',amount:4800,date:'2026-06-15',note:'Sample cash dividend'},{id:uid(),symbol:'DIAL.N0000',amount:3000,date:'2026-08-18',note:'Sample cash dividend'}];s.watchlist=[{symbol:'HNB.N0000',name:'Hatton National Bank',target:300},{symbol:'LOLC.N0000',name:'LOLC Holdings',target:480}];return s;}
let storageAvailable=true,storageWarning=false;
let state=emptyState(),lastSaved=emptyState(),revision=0,cloudReady=false,saving=false,cloud=null,failedDraft=null,cloudError='';
let page='overview',search='';
function syncStatus(text){$('#sync-status').textContent=text;}
function save(){
  if(!cloudReady||saving){state=structuredClone(lastSaved);render();throw Error('Wait until your portfolio is connected and saved.');}
  const next=validate(structuredClone(state));
  saving=true;syncStatus('Saving…');$('#application').classList.add('is-saving');
  const pending=cloud.commit(next,revision).then(newRevision=>{revision=newRevision;lastSaved=structuredClone(next);state=next;cloudError='';failedDraft=null;toast('All changes saved to Firebase.');}).catch(async error=>{
    failedDraft=next;state=structuredClone(lastSaved);cloudError=error.code==='portfolio/conflict'?error.message:'Changes could not be saved. Check your connection, then try again.';
    try{const latest=await cloud.load();if(latest.data){state=validate(latest.data);revision=latest.revision;lastSaved=structuredClone(state);}}catch{}
    toast(cloudError+' Download your unsaved changes before leaving.');
  }).finally(()=>{saving=false;$('#application').classList.remove('is-saving');syncStatus(cloudError?'Save failed':'Saved to Firebase');render();});
  render();return pending;
}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200);}
function ledger(trades=state.trades,openings=state.openings||[]){const holdings={};let realised=0;const timeline=[];for(const t of [...openings.map(o=>({...o,type:"opening"})),...trades].sort((a,b)=>a.date.localeCompare(b.date)||(a.type==="opening"?-1:b.type==="opening"?1:0))){const h=holdings[t.symbol]??={symbol:t.symbol,name:t.name,sector:t.sector,qty:0,cost:0,realised:0};h.name=t.name;h.sector=t.sector;if(t.type==='opening'){h.qty+=t.qty;h.cost+=t.cost;}else if(t.type==='buy'){h.qty+=t.qty;h.cost+=t.qty*t.price+t.fee;}else{if(t.qty>h.qty+1e-8)throw Error('Sell quantity exceeds shares available for '+t.symbol+' on '+t.date+'. Check transaction dates.');const basis=(h.cost/h.qty)*t.qty;const profit=t.qty*t.price-t.fee-basis;h.cost-=basis;h.qty-=t.qty;h.realised+=profit;realised+=profit;if(Math.abs(h.qty)<1e-8){h.qty=0;h.cost=0;}}timeline.push({date:t.date,cost:Object.values(holdings).reduce((sum,x)=>sum+x.cost,0)});}return {all:Object.values(holdings),holdings:Object.values(holdings).filter(h=>h.qty>1e-8).map(h=>{const q=portfolioQuote(h.symbol);return {...h,avg:h.cost/h.qty,quote:q?.price??null,quoteDate:q?.date??null,value:q?h.qty*q.price:null,gain:q?h.qty*q.price-h.cost:null};}),realised,timeline};}
function totals(){const l=ledger();let cost=0,value=0,gain=0,missing=0;for(const h of l.holdings){cost+=h.cost;if(h.value===null)missing++;else{value+=h.value;gain+=h.gain;}}return {...l,cost,value,gain,missing,dividend:state.dividends.reduce((n,d)=>n+d.amount,0)};}
function sign(n){return n>=0?'+':'−';}function gainText(n){return sign(n)+num(Math.abs(n));}function tone(n){return n>=0?'positive':'negative';}
function metric(label,value,foot,highlight=false){return `<div class="metric ${highlight?'highlight':''}"><div class="metric-label">${label}<span>↗</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function metrics(t){return `<div class="metrics">${metric('Portfolio market value',`<span class="currency">LKR</span>${num(t.value)}`,`${t.missing?`${t.missing} holding(s) need prices`:`${t.holdings.length} holdings · dated quotes`}`,true)}${metric('Unrealised gain / loss',`<span class="currency">LKR</span><span class="${tone(t.gain)}">${gainText(t.gain)}</span>`,`${t.cost&&!t.missing?`<span class="pill">${gainText(t.gain/t.cost*100)}%</span>`:''} On open positions${t.missing?' · partial':''}`)}${metric('Realised gain / loss',`<span class="currency">LKR</span><span class="${tone(t.realised)}">${gainText(t.realised)}</span>`,'Closed trades · after entered fees')}${metric('Dividends received',`<span class="currency">LKR</span>${num(t.dividend)}`,`${state.dividends.length} payment${state.dividends.length===1?'':'s'} recorded · net cash`)}</div>`;}
function chart(t){let points=t.timeline;if(!points.length)return '<div class="empty">Add your first transaction to see your cost basis over time.</div>';const max=Math.max(...points.map(p=>p.cost),1)*1.1;const pts=[{date:points[0].date,cost:0},...points];const x=i=>i/(pts.length-1)*600,y=n=>145-n/max*125;const path=pts.map((p,i)=>`${i?'L':'M'}${x(i)},${y(p.cost)}`).join(' ');return `<div class="chart-summary">${money(t.cost)}<small>current cost basis</small></div><div class="chart"><svg viewBox="0 0 600 165" preserveAspectRatio="none" role="img" aria-label="Cost basis across your transactions"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#a8c58b" stop-opacity=".35"/><stop offset="100%" stop-color="#a8c58b" stop-opacity=".02"/></linearGradient></defs>${[25,65,105,145].map(y=>`<line x1="0" x2="600" y1="${y}" y2="${y}" stroke="#edf1eb" stroke-dasharray="3 4"/>`).join('')}<path d="${path} L600,150 L0,150 Z" fill="url(#area)"/><path d="${path}" fill="none" stroke="#6d9460" stroke-width="2.5" vector-effect="non-scaling-stroke"/>${pts.slice(1).map((p,j)=>`<circle cx="${x(j+1)}" cy="${y(p.cost)}" r="3.5" fill="#6d9460"><title>${fmtDate(p.date)}: ${money(p.cost)}</title></circle>`).join('')}</svg></div><div class="chart-labels"><span>${fmtDate(points[0].date)}</span><span>${fmtDate(points.at(-1).date)}</span></div>`;}
function allocation(t){if(!t.value)return '<div class="empty">Enter prices to see sector allocation.</div>';const sectors={};for(const h of t.holdings)if(h.value!==null)sectors[h.sector]=(sectors[h.sector]||0)+h.value;const rows=Object.entries(sectors).sort((a,b)=>b[1]-a[1]);let p=0;const stops=rows.map(([s,v],i)=>{let start=p;p+=v/t.value*100;return `${colors[i%colors.length]} ${start}% ${p}%`;});return `<div class="allocation"><div class="donut" style="background:conic-gradient(${stops.join(',')})"><div class="donut-center">${rows.length}<small>SECTORS</small></div></div><div class="allocation-legend">${rows.map(([s,v],i)=>`<div class="allocation-row"><i style="background:${colors[i%colors.length]}"></i>${esc(s)}<b>${num(v/t.value*100,1)}%</b></div>`).join('')}</div></div>`;}
function holdingsTable(t,full=false){const rows=t.holdings.filter(h=>(h.symbol+' '+h.name).toLowerCase().includes(search.toLowerCase()));return `<div class="panel"><div class="panel-head"><div><h2>${full?'Your holdings':'Holdings at a glance'} <span style="color:#9aa78e;font-weight:400">${t.holdings.length}</span></h2><p class="panel-subtitle">A closer look at what you own.</p></div>${full?'<input class="search" id="search" placeholder="Search holdings…" aria-label="Search holdings">':'<a class="text-button" href="#holdings">All holdings ↗</a>'}</div><div class="table-wrap"><table><thead><tr><th>COMPANY / SYMBOL</th><th>SHARES</th><th>AVG. COST</th><th>LAST PRICE</th><th>MARKET VALUE</th><th>UNREALISED P&L</th>${full?'<th>WEIGHT</th>':''}</tr></thead><tbody>${rows.map(h=>`<tr><td><div class="company"><span class="ticker-icon">${esc(h.symbol.split('.')[0].slice(0,2))}</span><div><strong>${esc(h.symbol)}</strong><small>${esc(h.name)}</small></div></div></td><td>${num(h.qty,0)}</td><td>${num(h.avg)}</td><td>${h.quote===null?'—':num(h.quote)}<small>${h.quoteDate?fmtDate(h.quoteDate):'Price needed'}</small></td><td>${h.value===null?'—':num(h.value)}</td><td class="${tone(h.gain??0)}">${h.gain===null?'—':gainText(h.gain)}<small class="${tone(h.gain??0)}">${h.gain===null?'':gainText(h.gain/h.cost*100)+'%'}</small></td>${full?`<td>${h.value!==null&&t.value?num(h.value/t.value*100,1)+'%':'—'}</td>`:''}</tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty"><h3>Your next chapter starts here.</h3>Add a buy transaction to build your portfolio.</div>':''}</div><div class="panel-bottom"><span>Values in LKR · average cost includes entered buy fees</span><span>Dated CSE / entered prices</span></div></div>`;}
function transactions(){return `<div class="panel"><div class="panel-head"><div><h2>Transaction history</h2><p class="panel-subtitle">Every trade, with the details that matter.</p></div><button class="text-button" data-action="csv">Export CSV ↓</button></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>TYPE</th><th>SYMBOL</th><th>SHARES</th><th>PRICE</th><th>FEES</th><th>NET CASH FLOW</th><th></th></tr></thead><tbody>${[...state.trades].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${fmtDate(t.date)}</td><td><span class="badge ${t.type}">${t.type.toUpperCase()}</span></td><td>${esc(t.symbol)}</td><td>${num(t.qty,0)}</td><td>${num(t.price)}</td><td>${num(t.fee)}</td><td class="${t.type==='buy'?'':'positive'}">${t.type==='buy'?'−':'+'}${num(t.type==='buy'?t.qty*t.price+t.fee:t.qty*t.price-t.fee)}</td><td><button class="text-button" data-delete-trade="${t.id}" aria-label="Delete transaction">×</button></td></tr>`).join('')}</tbody></table>${!state.trades.length?'<div class="empty">No transactions yet. Add your first buy above.</div>':''}</div></div><div class="info-box">Sell gains use weighted average cost, including the buy fees you enter. Enter all fees from your broker’s contract note. Corporate actions such as splits and rights issues need manual adjustments; they are not applied automatically.</div>`;}
function dividends(t){return `<div class="metrics">${metric('Total cash dividends',`<span class="currency">LKR</span>${num(t.dividend)}`,'All recorded payments',true)}${metric('Payments recorded',num(state.dividends.length,0),'Cash amounts received')}</div><div class="panel"><div class="panel-head"><div><h2>Your dividend journal</h2><p class="panel-subtitle">Small returns. A growing story.</p></div><button class="button primary" data-action="dividend">＋ Record dividend</button></div><div class="table-wrap"><table><thead><tr><th>PAYMENT DATE</th><th>SYMBOL</th><th>NOTE</th><th>NET CASH RECEIVED</th><th></th></tr></thead><tbody>${[...state.dividends].sort((a,b)=>b.date.localeCompare(a.date)).map(d=>`<tr><td>${fmtDate(d.date)}</td><td>${esc(d.symbol)}</td><td>${esc(d.note)}</td><td class="positive">+${money(d.amount)}</td><td><button class="text-button" data-delete-dividend="${d.id}" aria-label="Delete dividend">×</button></td></tr>`).join('')}</tbody></table>${!state.dividends.length?'<div class="empty">Record a dividend payment to start your journal.</div>':''}</div></div>`;}
function watchlist(){return `<div class="info-box">Keep an eye on your next opportunity. Target prices are your own reference points. Prices are manual, and no automatic alerts are sent.</div><div class="panel"><div class="panel-head"><div><h2>On your radar</h2><p class="panel-subtitle">A little research today. A considered decision tomorrow.</p></div><button class="button primary" data-action="watch">＋ Add symbol</button></div><div class="table-wrap"><table><thead><tr><th>COMPANY / SYMBOL</th><th>ENTERED PRICE</th><th>MY TARGET PRICE</th><th>DISTANCE TO TARGET</th><th></th></tr></thead><tbody>${state.watchlist.map(w=>{const q=state.quotes[w.symbol];return `<tr><td><div class="company"><span class="ticker-icon">${esc(w.symbol.slice(0,2))}</span><div><strong>${esc(w.symbol)}</strong><small>${esc(w.name)}</small></div></div></td><td>${q?money(q.price):'—'}<small>${q?fmtDate(q.date):'Update prices to add'}</small></td><td>${money(w.target)}</td><td>${q?num((q.price-w.target)/w.target*100,1)+'%':'—'}</td><td><button class="text-button" data-delete-watch="${esc(w.symbol)}" aria-label="Remove watched symbol">×</button></td></tr>`;}).join('')}</tbody></table>${!state.watchlist.length?'<div class="empty">Add a symbol and your target price to start watching.</div>':''}</div></div>`;}
function settings(){return `<div class="settings-grid"><div class="panel settings-card"><h2>Your data, in your hands.</h2><p>Your portfolio is saved privately in Firebase and loads when you sign in on another device. Export a JSON backup regularly for your own records. Changes require an internet connection; “Saved to Firebase” confirms a completed save.</p><button class="button primary" data-action="backup">↓ Export backup</button><button class="button secondary" data-action="restore">↑ Restore backup</button></div><div class="panel settings-card"><h2>A fresh start</h2><p>${state.demo?'You are exploring sample investments and fictional prices. Start an empty portfolio when you are ready to add your real trades.':'Your personal portfolio is active. You can clear it, or load sample data to explore the dashboard. Export a backup first to keep your records.'}</p><button class="button secondary danger" data-action="clear">Start empty portfolio</button><button class="button secondary" data-action="demo">Load demo data</button></div><div class="panel settings-card"><h2>How your figures work</h2><p>All values are in Sri Lankan rupees (LKR). Open positions use weighted average cost, including entered buy fees. Realised gains deduct entered sell fees. Dividends use the net cash amount you record. The chart shows transaction cost basis, rather than historical market returns.</p></div><div class="panel settings-card"><h2>Price tracking</h2><p>At sign-in, this site fetches the latest scheduled CSE market snapshot. The collector runs on weekdays after market close (16:00 Sri Lanka time); GitHub may delay scheduled runs. Each quote keeps its own last-traded date. Your holdings stay private in Firebase. A newer manual quote takes priority. Missing quotes are marked partial. No broker connection or automatic trading. Written fundamental reviews are dated separately and are not regenerated automatically.</p><button class="button secondary" data-action="prices">↻ Update prices</button></div></div>`;}
const titles={overview:['Portfolio overview','The bigger picture. Every investment, in one place.'],holdings:['Your holdings','Know what you own. See where you stand.'],transactions:['Transactions','Your investing story, one trade at a time.'],dividends:['Dividends','Keep track of the income your investments bring.'],watchlist:['Your watchlist','Make room for your next considered investment.'],research:['Stock research','Understand the business. Put price movements in context.'],settings:['Data & settings','A personal space. With you in control.']};
function render(){const t=totals();if(!titles[page])page='overview';$('#page-title').textContent=titles[page][0];$('#page-subtitle').textContent=titles[page][1];$('#crumb').textContent=page==='settings'?'Data & settings':page[0].toUpperCase()+page.slice(1);document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#notice').innerHTML=state.demo?'<span>◈ <b>Demo portfolio</b> · Sample holdings and fictional prices. Make this space yours when you’re ready.</span><button data-action="clear">Start my portfolio →</button>':`<span>◈ <b>Your portfolio</b> · ${saving?'Saving to Firebase…':cloudError?'Save needs attention':'Saved privately in Firebase'} · Dated CSE / entered quotes${t.missing?' · '+t.missing+' missing quote(s)':''}</span><a href="#settings" class="text-button">Manage data →</a>`;if(cloudError)$('#notice').innerHTML='<span>'+esc(cloudError)+'</span><button data-action="unsaved">Download unsaved changes ↓</button>';$('#content').innerHTML=page==='overview'?`${metrics(t)}${portfolioInsights(t)}<div class="middle-grid"><div class="panel"><div class="panel-head"><div><h2>Your capital at work</h2><p class="panel-subtitle">Open-position cost basis across your transactions</p></div><span class="chart-legend"><i></i> Cost basis</span></div>${chart(t)}</div><div class="panel"><div class="panel-head"><div><h2>Portfolio allocation</h2><p class="panel-subtitle">By sector · latest available quotes</p></div><span style="color:#99a78e">◔</span></div>${allocation(t)}</div></div>${holdingsTable(t)}`:page==='holdings'?metrics(t)+holdingsTable(t,true):page==='research'?researchPage(t):page==='transactions'?openingBalances()+transactions():page==='dividends'?dividends(t):page==='watchlist'?watchlist():settings();if($('#research-symbol'))$('#research-symbol').onchange=e=>{selectedResearch=e.target.value;render();};if($('#search')){$('#search').value=search;$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};}}
function navigate(){page=location.hash.slice(1)||'overview';search='';render();}window.addEventListener('hashchange',navigate);
function field(name,label,type='text',value='',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
let onSave;
function modal(title,body,handler,saveLabel='Save'){ $('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#form-error').textContent='';$('#save-modal').textContent=saveLabel;onSave=handler;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
$('#close-modal').onclick=closeModal;$('#cancel-modal').onclick=closeModal;$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSave(new FormData(e.target));closeModal();}catch(err){$('#form-error').textContent=err.message;}};
const sym=s=>String(s).trim().toUpperCase();
function checkSymbol(s){if(!/^[A-Z0-9][A-Z0-9.\-]{0,24}$/.test(s))throw Error('Enter a valid symbol, for example JKH.N0000.');}
function positive(n,label,zero=false){if(!Number.isFinite(n)||(zero?n<0:n<=0))throw Error(label+' must be '+(zero?'zero or greater.':'greater than zero.'));return n;}
function checkDate(d){if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||Number.isNaN(Date.parse(d))||new Date(d+'T12:00:00Z').toISOString().slice(0,10)!==d||d>dateToday())throw Error('Use a valid date on or before today.');}
function tradeModal(){modal('Add a transaction',`<div class="form-grid"><label class="field">Transaction type<select name="type"><option value="buy">Buy shares</option><option value="sell">Sell shares</option></select></label>${field('date','Trade date','date',dateToday(),'required max="'+dateToday()+'"')}${field('symbol','CSE symbol','text','','required placeholder="e.g. JKH.N0000" list="symbols" maxlength="25"')}${field('name','Company name','text','','required maxlength="90" placeholder="e.g. John Keells Holdings"')}<label class="field full">Sector<select name="sector">${['Banks','Capital goods','Consumer services','Diversified financials','Energy','Food, beverage & tobacco','Food & staples retailing','Health care','Insurance','Materials','Real estate','Retailing','Telecommunication','Transportation','Utilities','Other'].map(s=>`<option>${s}</option>`).join('')}</select></label>${field('qty','Number of shares','number','','required min="1" step="1"')}${field('price','Price per share (LKR)','number','','required min="0.0001" step="any"')}${field('fee','Total broker fees (LKR)','number','0','required min="0" step="any"')}<label class="field"><small style="margin-top:26px">Enter fees from your contract note. No automatic fee or tax assumptions.</small></label></div><datalist id="symbols">${ledger().all.map(h=>`<option value="${esc(h.symbol)}">${esc(h.name)}</option>`).join('')}</datalist>`,f=>{const t={id:uid(),type:f.get('type'),date:f.get('date'),symbol:sym(f.get('symbol')),name:String(f.get('name')).trim(),sector:f.get('sector'),qty:Number(f.get('qty')),price:Number(f.get('price')),fee:Number(f.get('fee'))};checkSymbol(t.symbol);checkDate(t.date);positive(t.qty,'Shares');if(!Number.isInteger(t.qty))throw Error('Shares must be whole numbers.');positive(t.price,'Price');positive(t.fee,'Fees',true);if(!t.name)throw Error('Enter a company name.');ledger([...state.trades,t]);state.trades.push(t);save();toast('Saving transaction…');},'Save transaction');$('#modal-body [name=symbol]').onchange=e=>{const h=ledger().all.find(h=>h.symbol===sym(e.target.value));if(h){$('#modal-body [name=name]').value=h.name;$('#modal-body [name=sector]').value=h.sector;}};}
function priceModal(){const symbols=[...new Set([...ledger().holdings.map(h=>h.symbol),...state.watchlist.map(w=>w.symbol)])];if(!symbols.length){toast('Add a holding or watchlist symbol first.');return;}modal('Update market prices',`<p class="panel-subtitle" style="line-height:1.7;margin-bottom:20px">Enter the latest prices from your chosen source. Leave a field blank to keep its existing price.</p>${field('date','Prices as of','date',dateToday(),'required max="'+dateToday()+'"')}${symbols.map((s,i)=>`<label class="quote-row"><span>${esc(s)}<small>${state.quotes[s]?'Previous: '+money(state.quotes[s].price)+' · '+(state.quotes[s].date?fmtDate(state.quotes[s].date):'undated statement'):'No price entered'}</small></span><input aria-label="Price for ${esc(s)}" name="q${i}" type="number" min="0.0001" step="any" placeholder="LKR"></label>`).join('')}`,f=>{checkDate(f.get('date'));const next={...state.quotes};let changed=0;symbols.forEach((s,i)=>{const raw=f.get('q'+i);if(raw!==''){next[s]={price:positive(Number(raw),'Price'),date:f.get('date')};changed++;}});if(!changed)throw Error('Enter at least one price to update.');state.quotes=next;save();toast('Saving prices…');},'Update prices');}
function dividendModal(){modal('Record a dividend',`<div class="form-grid">${field('symbol','CSE symbol','text','','required placeholder="e.g. COMB.N0000" maxlength="25"')}${field('date','Payment date','date',dateToday(),'required max="'+dateToday()+'"')}${field('amount','Net cash received (LKR)','number','','required min="0.01" step="any"')}${field('note','Note (optional)','text','','maxlength="120" placeholder="e.g. Final dividend"')}</div>`,f=>{const d={id:uid(),symbol:sym(f.get('symbol')),date:f.get('date'),amount:positive(Number(f.get('amount')),'Amount'),note:f.get('note')};checkSymbol(d.symbol);checkDate(d.date);state.dividends.push(d);save();toast('Saving dividend…');},'Record dividend');}
function watchModal(){modal('Add to your watchlist',`<div class="form-grid">${field('symbol','CSE symbol','text','','required placeholder="e.g. HNB.N0000" maxlength="25"')}${field('name','Company name','text','','required maxlength="90"')}${field('target','My target price (LKR)','number','','required min="0.0001" step="any"')}</div>`,f=>{const w={symbol:sym(f.get('symbol')),name:String(f.get('name')).trim(),target:positive(Number(f.get('target')),'Target price')};checkSymbol(w.symbol);if(!w.name)throw Error('Enter a company name.');if(state.watchlist.some(x=>x.symbol===w.symbol))throw Error('That symbol is already on your watchlist.');state.watchlist.push(w);save();toast('Saving watchlist…');},'Add symbol');}
function confirmChange(title,text,handler){modal(title,`<p class="info-box">${esc(text)}</p>`,()=>{handler();save();toast('Saving portfolio…');},'Continue');}
function download(text,filename,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const actions={refreshMarket,unsaved:()=>{if(failedDraft)download(JSON.stringify(failedDraft,null,2),'serendib-unsaved-'+dateToday()+'.json','application/json');},trade:tradeModal,prices:priceModal,dividend:dividendModal,watch:watchModal,backup:()=>download(JSON.stringify(state,null,2),'serendib-backup-'+dateToday()+'.json','application/json'),restore:()=>$('#import-file').click(),clear:()=>confirmChange('Start your own portfolio',state.demo?'This will remove the sample records and give you an empty portfolio.':'This will replace your cloud portfolio with an empty one on all devices. Export a backup from Data & settings first to keep your records.',()=>state=emptyState()),demo:()=>confirmChange('Load demo portfolio','This replaces your current records with fictional sample data. Export a backup first to keep your current portfolio. This changes the cloud portfolio on all your devices.',()=>state=demoState()),csv:()=>{const rows=[['Date','Type','Symbol','Company','Sector','Shares','Price LKR','Fees LKR'],...state.trades.map(t=>[t.date,t.type,t.symbol,t.name,t.sector,t.qty,t.price,t.fee])];download(rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'serendib-trades-'+dateToday()+'.csv','text/csv');}};
$('#trade-button').onclick=tradeModal;$('#prices-button').onclick=priceModal;
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a)actions[a.dataset.action]?.();const del=e.target.closest('[data-delete-trade]');if(del)confirmChange('Remove this transaction?','The transaction will be removed and your portfolio recalculated.',()=>{const next=state.trades.filter(t=>t.id!==del.dataset.deleteTrade);ledger(next);state.trades=next;});const d=e.target.closest('[data-delete-dividend]');if(d)confirmChange('Remove dividend?','This removes the selected dividend payment.',()=>state.dividends=state.dividends.filter(x=>x.id!==d.dataset.deleteDividend));const w=e.target.closest('[data-delete-watch]');if(w){state.watchlist=state.watchlist.filter(x=>x.symbol!==w.dataset.deleteWatch);save();toast('Saving watchlist…');}});
function validate(s){if(!s||![1,2].includes(s.version)||!Array.isArray(s.trades)||!Array.isArray(s.dividends)||!Array.isArray(s.watchlist)||!s.quotes||typeof s.quotes!=='object'||Array.isArray(s.quotes))throw Error('Invalid backup format.');if(s.trades.length>100000||s.dividends.length>100000||s.watchlist.length>10000)throw Error('Backup is too large.');const next=emptyState();next.demo=s.demo===true;const ids=new Set();const id=v=>{if(typeof v!=='string'||!/^[A-Za-z0-9_-]{1,90}$/.test(v)||ids.has(v))throw Error('Invalid or duplicate record ID.');ids.add(v);return v;};const str=(v,max)=>{if(typeof v!=='string'||!v.trim()||v.length>max)throw Error('Invalid text field.');return v;};next.trades=s.trades.map(t=>{checkSymbol(t.symbol);checkDate(t.date);if(!['buy','sell'].includes(t.type))throw Error('Invalid transaction type.');positive(t.qty,'Shares');if(!Number.isSafeInteger(t.qty))throw Error('Invalid share quantity.');positive(t.price,'Price');positive(t.fee,'Fees',true);return {id:id(t.id),type:t.type,symbol:t.symbol,date:t.date,name:str(t.name,90),sector:str(t.sector,90),qty:t.qty,price:t.price,fee:t.fee};});next.dividends=s.dividends.map(d=>{checkSymbol(d.symbol);checkDate(d.date);positive(d.amount,'Amount');return {id:id(d.id),symbol:d.symbol,date:d.date,amount:d.amount,note:typeof d.note==='string'?d.note.slice(0,120):''};});const symbols=new Set();next.watchlist=s.watchlist.map(w=>{checkSymbol(w.symbol);if(symbols.has(w.symbol))throw Error('Duplicate watchlist symbol.');symbols.add(w.symbol);positive(w.target,'Target price');return {symbol:w.symbol,name:str(w.name,90),target:w.target};});for(const [symbol,q] of Object.entries(s.quotes)){checkSymbol(symbol);positive(q.price,'Price');if(q.date!==null||q.source!=='statement')checkDate(q.date);next.quotes[symbol]={price:q.price,date:q.date,...(q.source==='statement'?{source:'statement'}:{})};}
if(s.openings!==undefined&&!Array.isArray(s.openings))throw Error('Invalid opening balances.');
if((s.openings||[]).length>500)throw Error('Too many opening balances.');
const openingSymbols=new Set();next.openings=(s.openings||[]).map(o=>{checkSymbol(o.symbol);checkDate(o.date);positive(o.qty,'Shares');positive(o.cost,'Cost');if(!Number.isSafeInteger(o.qty)||openingSymbols.has(o.symbol))throw Error('Invalid or duplicate opening holding.');openingSymbols.add(o.symbol);return {id:id(o.id),symbol:o.symbol,name:str(o.name,90),sector:str(o.sector,90),qty:o.qty,cost:o.cost,date:o.date};});
if(s.statement){const v=s.statement;checkDate(v.importedAt);if(v.date)checkDate(v.date);const fee=Number(v.sellFeeRate);if(!Number.isFinite(fee)||fee<0||fee>.1)throw Error('Invalid fee estimate.');next.statement={importedAt:v.importedAt,date:v.date||null,sellFeeRate:fee};}
if(s.research){if(typeof s.research!=='object'||Array.isArray(s.research)||Object.keys(s.research).length>500)throw Error('Invalid research.');for(const [symbol,r] of Object.entries(s.research)){checkSymbol(symbol);if(!r||typeof r!=='object')throw Error('Invalid research note.');next.research[symbol]={asOf:str(r.asOf,40),period:str(r.period,200),metrics:(r.metrics||[]).slice(0,12).map(m=>({label:str(m.label,120),value:str(m.value,200)})),summary:str(r.summary,6000),watch:str(r.watch,3000),sources:(r.sources||[]).slice(0,10).map(x=>{const u=new URL(x.url);if(u.protocol!=='https:')throw Error('Invalid research link.');return {title:str(x.title,200),url:u.href};})};}}
ledger(next.trades,next.openings);return next;}
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('Use a backup smaller than 10 MB.');const next=validate(JSON.parse(await file.text()));confirmChange('Restore this backup?',`Replace your current data with ${next.openings.length} opening balances, ${next.trades.length} trades, ${next.dividends.length} dividend payments and ${next.watchlist.length} watchlist symbols?`,()=>state=next);}catch(err){toast('Could not restore: '+err.message);}};
$('#today').textContent=new Date().toLocaleDateString('en-GB',{timeZone:'Asia/Colombo',day:'numeric',month:'short',year:'numeric'});
navigate();
document.addEventListener('click',event=>{if(saving){event.preventDefault();event.stopImmediatePropagation();}},true);
$('#login-form').onsubmit=async event=>{event.preventDefault();const button=$('#login-submit');button.disabled=true;$('#login-message').textContent='Signing in…';try{await cloud.signIn($('#login-email').value.trim(),$('#login-password').value);$('#login-password').value='';}catch(error){$('#login-message').textContent=error.code==='auth/too-many-requests'?'Too many attempts. Please wait and try again.':error.code==='auth/network-request-failed'?'Cannot reach Firebase. Check your connection and try again.':'Could not sign in ('+(error.code||'unknown')+'). Check your email and password.';}finally{button.disabled=false;}};
$('#reset-password').onclick=async()=>{const email=$('#login-email').value.trim();if(!email||!$('#login-email').checkValidity()){$('#login-message').textContent='Enter your account email address first.';$('#login-email').focus();return;}$('#reset-password').disabled=true;try{await cloud.resetPassword(email);$('#login-message').textContent='If this email has an account, a password setup link is on its way. Check your inbox and spam folder.';}catch(error){$('#login-message').textContent=error.code==='auth/too-many-requests'?'Please wait before requesting another email.':'Could not send the setup email. Please try again.';}finally{$('#reset-password').disabled=false;}};
$('#sign-out').onclick=async()=>{if(saving)return;await cloud.signOut();};
$('#retry-portfolio').onclick=async()=>{await cloud.retryLoad();};
let stopCloud=null,authGeneration=0;
import('./cloud.js?v=20261027b').then(api=>{cloud=api;$('#login-submit').disabled=false;$('#login-submit').textContent='Sign in →';$('#reset-password').disabled=false;$('#login-message').textContent='';api.observeAuth(async(user,error)=>{
  $('#retry-portfolio').hidden=true;const generation=++authGeneration;if(stopCloud){stopCloud();stopCloud=null;}cloudReady=false;revision=0;state=emptyState();lastSaved=emptyState();failedDraft=null;cloudError='';closeModal();$('#application').hidden=true;$('#login-screen').hidden=false;
  if(!user){$('#login-message').textContent=error||'';render();return;}
  $('#login-message').textContent='Loading your private portfolio…';
  try{const snapshot=await api.load();if(generation!==authGeneration)return;state=snapshot.data?validate(snapshot.data):emptyState();lastSaved=structuredClone(state);revision=snapshot.revision;cloudReady=true;$('#login-screen').hidden=true;$('#application').hidden=false;syncStatus('Saved to Firebase');render();refreshMarket();
    stopCloud=api.subscribe(next=>{if(generation!==authGeneration||saving||next.revision<=revision)return;try{state=next.data?validate(next.data):emptyState();revision=next.revision;lastSaved=structuredClone(state);syncStatus('Saved to Firebase');render();}catch{cloudReady=false;syncStatus('Data needs attention');toast('Cloud data could not be read. Contact support before making changes.');}},()=>{syncStatus('Connection interrupted');toast('Cloud connection interrupted. Saves require a connection.');});
  }catch(error){if(generation!==authGeneration)return;cloudReady=false;$('#application').hidden=true;$('#login-screen').hidden=false;$('#retry-portfolio').hidden=false;const code=error.code||'data-validation';$('#login-message').textContent='Signed in, but portfolio loading failed ('+code+'). Use Retry loading portfolio. Your password does not need resetting.';console.warn('Portfolio load failed:',code);$('#login-submit').disabled=false;}
});}).catch(()=>{$('#login-message').textContent='Firebase could not connect. Check your internet connection, then reload this page.';});
